export const LiquidationStatuses = {
  APROBADA: 'APROBADA',
  RECHAZADA: 'RECHAZADA',
  PENDIENTE_APROBACION: 'PENDIENTE_APROBACION',
} as const;
export type LiquidationStatus = typeof LiquidationStatuses[keyof typeof LiquidationStatuses];

export const ClaimStatuses = {
  REGISTRADO: 'REGISTRADO',
  LIQUIDADO: 'LIQUIDADO',
  RECHAZADO: 'RECHAZADO',
  PENDIENTE_REVISION: 'PENDIENTE_REVISION',
} as const;
export type ClaimStatus = typeof ClaimStatuses[keyof typeof ClaimStatuses];

export const ReasonCodes = {
  POLIZA_NO_VIGENTE: 'POLIZA_NO_VIGENTE',
  FUERA_DE_VIGENCIA: 'FUERA_DE_VIGENCIA',
  DENUNCIA_EXTEMPORANEA: 'DENUNCIA_EXTEMPORANEA',
  COBERTURA_NO_CONTRATADA: 'COBERTURA_NO_CONTRATADA',
  EN_PERIODO_CARENCIA: 'EN_PERIODO_CARENCIA',
  PRIMA_EN_MORA: 'PRIMA_EN_MORA',
