function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year: number, month: number): number {
  if (month === 2) {
    return isLeapYear(year) ? 29 : 28;
  }
  return month === 4 || month === 6 || month === 9 || month === 11 ? 30 : 31;
}

function daysFromCivil(yearInput: number, month: number, day: number): number {
  const year = month <= 2 ? yearInput - 1 : yearInput;
  const era = Math.floor(year / 400);
  const yearOfEra = year - era * 400;
  const shiftedMonth = month > 2 ? month - 3 : month + 9;
  const dayOfYear = Math.floor((153 * shiftedMonth + 2) / 5) + day - 1;
  const dayOfEra = yearOfEra * 365 + Math.floor(yearOfEra / 4) - Math.floor(yearOfEra / 100) + dayOfYear;
  return era * 146097 + dayOfEra - 719468;
}

/** Fecha de calendario sin hora (equivale a TRUNC(fecha) del legacy). */
export class CalendarDate {
  readonly epochDay: number;

  constructor(epochDay: number) {
    this.epochDay = epochDay;
  }

  /** Interpreta YYYY-MM-DD (se ignora una hora opcional). Devuelve null si es inválida. */
  static fromIso(text: string): CalendarDate | null {
    const match = /^([0-9]{4})-([0-9]{2})-([0-9]{2})([T ].*)?$/.exec(text);
    if (match === null) {
      return null;
    }
    const year = parseInt(match[1], 10);
    const month = parseInt(match[2], 10);
    const day = parseInt(match[3], 10);
    if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) {
      return null;
    }
    return new CalendarDate(daysFromCivil(year, month, day));
  }

  /** Días calendario transcurridos desde `other` hasta esta fecha. */
  daysSince(other: CalendarDate): number {
    return this.epochDay - other.epochDay;
  }

  isBefore(other: CalendarDate): boolean {
    return this.epochDay < other.epochDay;
  }

  isAfter(other: CalendarDate): boolean {
    return this.epochDay > other.epochDay;
  }
}

/** Marcas de ajuste inmutables, en el orden en que se aplicaron. */
export class Observations {
  readonly marks: readonly string[];

  constructor(marks: readonly string[]) {
    this.marks = marks;
  }

  static empty(): Observations {
    return new Observations([]);
  }

  /**
   * Agrega una marca al final.
   * @rule R-026
   */
  with(mark: string): Observations {
    return new Observations([...this.marks, mark]);
  }

  /**
   * Marcas separadas por ';'.
   * @rule R-026
   */
  toString(): string {
    return this.marks.join(';');
  }
}

import { Decimal } from '../shared/decimal.ts';

/**
 * ROUND(amount * percent / 100, 2) con redondeo half-up.
 * @rule R-025
 */
export function percentOf(amount: Decimal, percent: Decimal): Decimal {
  return amount.times(percent).dividedBy(Decimal.of(100), 2, 'HALF_UP');
}

/**
 * Ajusta un valor a la escala monetaria 2 (NUMBER(14,2)).
 * @rule R-025
 */
export function toAmount(value: Decimal): Decimal {
  return value.setScale(2, 'HALF_UP');
}

export function zeroAmount(): Decimal {
  return Decimal.of('0.00');
}

import type { Decimal } from '../shared/decimal.ts';
import type { Observations } from './Observations.ts';

/** Importe calculado junto con las observaciones acumuladas hasta ese paso. */
