import type { Decimal } from '../shared/decimal.ts';

/** Error técnico interno: parámetro requerido inexistente. El servicio lo convierte en el error 20010. */
export class ParameterNotDefinedError extends Error {
  readonly parameterCode: string;

  constructor(parameterCode: string) {
    super('Parametro no definido: ' + parameterCode);
    this.name = 'ParameterNotDefinedError';
    this.parameterCode = parameterCode;
  }
}

/** Parámetros de negocio inmutables (equivalente a LS_PARAMETROS). */
export class BusinessParameters {
  readonly values: ReadonlyMap<string, Decimal>;

  constructor(values: ReadonlyMap<string, Decimal>) {
    this.values = values;
  }

  /**
   * Obtiene un parámetro obligatorio.
   * @rule R-003
   */
  require(code: string): Decimal {
    const value = this.values.get(code);
    if (value === undefined) {
      throw new ParameterNotDefinedError(code);
    }
    return value;
  }
}

