import type { Decimal } from '../shared/decimal.ts';
import type { ClaimStatus, LiquidationStatus, ReasonCode } from './Codes.ts';
import { LiquidationStatuses } from './Codes.ts';
import { claimStatusFor } from '../decision/ClaimStatusMapping.ts';
import type { Observations } from './Observations.ts';
import { zeroAmount } from './Rounding.ts';

export interface LiquidationProps {
  readonly baseAmount: Decimal;
  readonly deductibleAmount: Decimal;
  readonly coveredAmount: Decimal;
  readonly withholdingAmount: Decimal;
  readonly netAmount: Decimal;
  readonly status: LiquidationStatus;
  readonly reasonCode: ReasonCode;
  readonly observations: Observations;
}

/** Resultado de la liquidación de un siniestro. */
export class Liquidation {
  readonly baseAmount: Decimal;
  readonly deductibleAmount: Decimal;
  readonly coveredAmount: Decimal;
  readonly withholdingAmount: Decimal;
  readonly netAmount: Decimal;
  readonly status: LiquidationStatus;
  readonly reasonCode: ReasonCode;
  readonly observations: string;
  readonly claimNewStatus: ClaimStatus;

  constructor(props: LiquidationProps) {
    this.baseAmount = props.baseAmount;
    this.deductibleAmount = props.deductibleAmount;
    this.coveredAmount = props.coveredAmount;
    this.withholdingAmount = props.withholdingAmount;
    this.netAmount = props.netAmount;
    this.status = props.status;
    this.reasonCode = props.reasonCode;
    this.observations = props.observations.toString();
    this.claimNewStatus = claimStatusFor(props.status);
  }

  /**
   * Liquidación rechazada: todos los importes en cero y observaciones acumuladas.
   * @rule R-023
   */
  static rejected(reasonCode: ReasonCode, observations: Observations): Liquidation {
    return new Liquidation({
      baseAmount: zeroAmount(),
      deductibleAmount: zeroAmount(),
      coveredAmount: zeroAmount(),
      withholdingAmount: zeroAmount(),
      netAmount: zeroAmount(),
      status: LiquidationStatuses.RECHAZADA,
      reasonCode,
      observations,
    });
  }
}

import type { Liquidation } from './Liquidation.ts';

export interface LiquidationSuccess {
  readonly ok: true;
  readonly liquidation: Liquidation;
}

export interface LiquidationFailure {
  readonly ok: false;
  readonly errorCode: string;
}

/** Resultado tipado: los errores de negocio y técnicos no son excepciones. */
export type LiquidationOutcome = LiquidationSuccess | LiquidationFailure;

export function success(liquidation: Liquidation): LiquidationOutcome {
  return { ok: true, liquidation };
}

export function failure(errorCode: string): LiquidationOutcome {
  return { ok: false, errorCode };
}

import type { ClaimStatus, LiquidationStatus } from '../model/Codes.ts';
import { ClaimStatuses, LiquidationStatuses } from '../model/Codes.ts';

/**
 * Estado del siniestro según el estado de la liquidación.
 * @rule R-024
 */
export function claimStatusFor(status: LiquidationStatus): ClaimStatus {
  if (status === LiquidationStatuses.APROBADA) {
    return ClaimStatuses.LIQUIDADO;
  }
  if (status === LiquidationStatuses.RECHAZADA) {
    return ClaimStatuses.RECHAZADO;
  }
  return ClaimStatuses.PENDIENTE_REVISION;
}

import { ClaimStatuses } from '../model/Codes.ts';

/**
 * Solo se liquidan siniestros REGISTRADO; cualquier otro estado produce el error 20001.
 * @rule R-001
 */
export function isLiquidable(claimStatus: string): boolean {
  return claimStatus === ClaimStatuses.REGISTRADO;
}

import { Decimal } from '../shared/decimal.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import { ParameterCodes } from '../model/Codes.ts';
import type { LiquidationRequest } from '../model/LiquidationRequest.ts';
import { percentOf } from '../model/Rounding.ts';

/** Sospecha de fraude: siniestro temprano con reclamo cercano al límite de cobertura. */
export class FraudAlertSpecification {
  /**
   * dias_desde_inicio <= DIAS_ALERTA_FRAUDE y claimed_amount >= ROUND(limite * PCT_ALERTA_FRAUDE / 100, 2).
   * @rule R-021
   * @rule R-025
   */
  isSatisfiedBy(request: LiquidationRequest, parameters: BusinessParameters): boolean {
    const maxDays = parameters.require(ParameterCodes.DIAS_ALERTA_FRAUDE);
    const percent = parameters.require(ParameterCodes.PCT_ALERTA_FRAUDE);
    const daysFromStart = Decimal.of(request.occurrenceDate.daysSince(request.policyStartDate));
    const threshold = percentOf(request.coverageLimit, percent);
    return daysFromStart.lte(maxDays) && request.claimedAmount.gte(threshold);
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { LiquidationStatus, ReasonCode } from '../model/Codes.ts';
import { LiquidationStatuses, ParameterCodes, ReasonCodes } from '../model/Codes.ts';
import type { LiquidationRequest } from '../model/LiquidationRequest.ts';
import type { FraudAlertSpecification } from './FraudAlertSpecification.ts';

export interface ApprovalDecision {
  readonly status: LiquidationStatus;
  readonly reasonCode: ReasonCode;
}

/** Decide el estado final: la sospecha de fraude tiene prioridad sobre el tope automático. */
export class ApprovalPolicy {
  readonly fraudAlert: FraudAlertSpecification;

  constructor(fraudAlert: FraudAlertSpecification) {
    this.fraudAlert = fraudAlert;
  }

  /**
   * @rule R-021
   * @rule R-022
   */
  decide(request: LiquidationRequest, netAmount: Decimal, parameters: BusinessParameters): ApprovalDecision {
    if (this.fraudAlert.isSatisfiedBy(request, parameters)) {
      return { status: LiquidationStatuses.PENDIENTE_APROBACION, reasonCode: ReasonCodes.SOSPECHA_FRAUDE };
    }
    const cap = parameters.require(ParameterCodes.TOPE_AUTO_APROBACION);
    if (netAmount.gt(cap)) {
      return { status: LiquidationStatuses.PENDIENTE_APROBACION, reasonCode: ReasonCodes.SUPERA_TOPE_AUTOMATICO };
    }
    return { status: LiquidationStatuses.APROBADA, reasonCode: ReasonCodes.LIQUIDACION_AUTOMATICA };
  }
}

import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { ReasonCode } from '../model/Codes.ts';
import type { LiquidationRequest } from '../model/LiquidationRequest.ts';
import type { Observations } from '../model/Observations.ts';

export interface EligibilityContext {
  readonly request: LiquidationRequest;
  readonly parameters: BusinessParameters;
  readonly observations: Observations;
}

export interface EligibilityVerdict {
  readonly rejection: ReasonCode | null;
  readonly observations: Observations;
}

/** Validación de procedencia. Devuelve el motivo de rechazo o null si pasa. */
export interface EligibilityRule {
  evaluate(context: EligibilityContext): EligibilityVerdict;
}

export function passed(observations: Observations): EligibilityVerdict {
  return { rejection: null, observations };
}

export function rejected(reason: ReasonCode, observations: Observations): EligibilityVerdict {
  return { rejection: reason, observations };
}

import { Decimal } from '../shared/decimal.ts';
import { Categories, Lines, Marks, ParameterCodes, PolicyStatuses, ReasonCodes } from '../model/Codes.ts';
import type { EligibilityContext, EligibilityRule, EligibilityVerdict } from './EligibilityRule.ts';
import { passed, rejected } from './EligibilityRule.ts';

/** Solo se indemnizan pólizas VIGENTE. */
export class PolicyActiveRule implements EligibilityRule {
  /** @rule R-005 */
  evaluate(context: EligibilityContext): EligibilityVerdict {
    if (context.request.policyStatus === PolicyStatuses.VIGENTE) {
      return passed(context.observations);
    }
    return rejected(ReasonCodes.POLIZA_NO_VIGENTE, context.observations);
  }
}

/** La ocurrencia debe estar dentro de la vigencia, ambos extremos incluidos. */
export class PolicyPeriodRule implements EligibilityRule {
  /** @rule R-006 */
  evaluate(context: EligibilityContext): EligibilityVerdict {
    const { occurrenceDate, policyStartDate, policyEndDate } = context.request;
    if (occurrenceDate.isBefore(policyStartDate) || occurrenceDate.isAfter(policyEndDate)) {
      return rejected(ReasonCodes.FUERA_DE_VIGENCIA, context.observations);
    }
    return passed(context.observations);
  }
}

/** Plazo máximo de denuncia: el último día del plazo todavía es válido. */
export class ReportingDeadlineRule implements EligibilityRule {
  /** @rule R-007 */
  evaluate(context: EligibilityContext): EligibilityVerdict {
    const { request, parameters } = context;
    const limitCode = request.lineOfBusiness === Lines.VIDA
      ? ParameterCodes.DIAS_MAX_DENUNCIA_VIDA
      : ParameterCodes.DIAS_MAX_DENUNCIA;
    const maxDays = parameters.require(limitCode);
    const elapsed = Decimal.of(request.reportDate.daysSince(request.occurrenceDate));
    if (elapsed.gt(maxDays)) {
      return rejected(ReasonCodes.DENUNCIA_EXTEMPORANEA, context.observations);
    }
    return passed(context.observations);
  }
}

/** La cobertura reclamada debe estar contratada en la póliza. */
export class CoverageContractedRule implements EligibilityRule {
  /** @rule R-008 */
  evaluate(context: EligibilityContext): EligibilityVerdict {
    if (context.request.coverageFound) {
      return passed(context.observations);
    }
    return rejected(ReasonCodes.COBERTURA_NO_CONTRATADA, context.observations);
  }
}

/** Carencia: con exactamente los días de carencia cumplidos la cobertura ya está activa. */
export class WaitingPeriodRule implements EligibilityRule {
  /** @rule R-009 */
  evaluate(context: EligibilityContext): EligibilityVerdict {
    const { request } = context;
    const elapsed = Decimal.of(request.occurrenceDate.daysSince(request.policyStartDate));
    if (elapsed.lt(request.waitingDays)) {
      return rejected(ReasonCodes.EN_PERIODO_CARENCIA, context.observations);
    }
    return passed(context.observations);
  }
}

/** Mora de prima con tolerancia para clientes VIP. */
export class PremiumArrearsRule implements EligibilityRule {
  /** @rule R-010 */
  evaluate(context: EligibilityContext): EligibilityVerdict {
    const { request, parameters, observations } = context;
    if (!request.pendingPremium.gt(Decimal.of(0))) {
      return passed(observations);
    }
    const tolerance = parameters.require(ParameterCodes.TOLERANCIA_MORA_VIP);
    if (request.customerCategory === Categories.VIP && request.pendingPremium.lte(tolerance)) {
      return passed(observations.with(Marks.TOLERANCIA_MORA_VIP));
    }
    return rejected(ReasonCodes.PRIMA_EN_MORA, observations);
  }
}

import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { LiquidationRequest } from '../model/LiquidationRequest.ts';
import { Observations } from '../model/Observations.ts';
import type { EligibilityRule, EligibilityVerdict } from './EligibilityRule.ts';
import { passed } from './EligibilityRule.ts';

/** Evalúa las reglas de procedencia en orden fijo; la primera que falla determina el rechazo. */
export class EligibilityPipeline {
  readonly rules: readonly EligibilityRule[];

  constructor(rules: readonly EligibilityRule[]) {
    this.rules = rules;
  }

  /**
   * Orden: póliza vigente, vigencia, denuncia, cobertura, carencia, mora.
   * @rule R-004
   */
  evaluate(request: LiquidationRequest, parameters: BusinessParameters): EligibilityVerdict {
    let observations = Observations.empty();
    for (const rule of this.rules) {
      const verdict = rule.evaluate({ request, parameters, observations });
      if (verdict.rejection !== null) {
        return verdict;
      }
      observations = verdict.observations;
    }
    return passed(observations);
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { AmountWithMarks } from '../model/AmountWithMarks.ts';
import { Marks } from '../model/Codes.ts';
import type { Observations } from '../model/Observations.ts';
import { toAmount } from '../model/Rounding.ts';

/** Monto base: el menor entre lo reclamado y el límite de cobertura. */
export class BaseAmountCalculator {
  /** @rule R-011 */
  calculate(claimedAmount: Decimal, coverageLimit: Decimal, observations: Observations): AmountWithMarks {
    if (claimedAmount.gt(coverageLimit)) {
      return { amount: toAmount(coverageLimit), observations: observations.with(Marks.LIMITE_COBERTURA) };
    }
    return { amount: toAmount(claimedAmount), observations };
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { AmountWithMarks } from '../model/AmountWithMarks.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import { DeductibleTypes, Marks, ParameterCodes } from '../model/Codes.ts';
import type { Observations } from '../model/Observations.ts';
import { percentOf, toAmount, zeroAmount } from '../model/Rounding.ts';

export interface DeductibleStrategy {
  calculate(base: Decimal, value: Decimal, parameters: BusinessParameters, observations: Observations): AmountWithMarks;
}

/** Deducible fijo: es el monto de la póliza, sin mínimo. */
export class FixedDeductibleStrategy implements DeductibleStrategy {
  /** @rule R-012 */
  calculate(_base: Decimal, value: Decimal, _parameters: BusinessParameters, observations: Observations): AmountWithMarks {
    return { amount: toAmount(value), observations };
  }
}

/** Deducible porcentual sobre el monto base, con mínimo DEDUCIBLE_MINIMO. */
export class PercentageDeductibleStrategy implements DeductibleStrategy {
  /**
   * @rule R-013
   * @rule R-025
   */
  calculate(base: Decimal, value: Decimal, parameters: BusinessParameters, observations: Observations): AmountWithMarks {
    const minimum = parameters.require(ParameterCodes.DEDUCIBLE_MINIMO);
    const computed = percentOf(base, value);
    if (computed.lt(minimum)) {
      return { amount: toAmount(minimum), observations: observations.with(Marks.DEDUCIBLE_MINIMO) };
    }
    return { amount: computed, observations };
  }
}

/** Tipo de deducible no reconocido: sin deducible. */
export class NoDeductibleStrategy implements DeductibleStrategy {
  calculate(_base: Decimal, _value: Decimal, _parameters: BusinessParameters, observations: Observations): AmountWithMarks {
    return { amount: zeroAmount(), observations };
  }
}

/**
 * Selecciona la estrategia según deductible_type.
 * @rule R-012
 * @rule R-013
 */
export function selectDeductibleStrategy(deductibleType: string): DeductibleStrategy {
  if (deductibleType === DeductibleTypes.FIJO) {
    return new FixedDeductibleStrategy();
  }
  if (deductibleType === DeductibleTypes.PORCENTAJE) {
    return new PercentageDeductibleStrategy();
  }
  return new NoDeductibleStrategy();
}

import { Decimal } from '../shared/decimal.ts';
import type { AmountWithMarks } from '../model/AmountWithMarks.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import { Categories, Marks, ParameterCodes } from '../model/Codes.ts';
import type { LiquidationRequest } from '../model/LiquidationRequest.ts';
import { percentOf } from '../model/Rounding.ts';
import { selectDeductibleStrategy } from './DeductibleStrategies.ts';

/** Descuento VIP sobre el deducible, aplicado después del mínimo. */
export class VipDeductibleDiscount {
  /**
   * @rule R-014
   * @rule R-025
   */
  apply(customerCategory: string, deductible: AmountWithMarks, parameters: BusinessParameters): AmountWithMarks {
    if (customerCategory !== Categories.VIP || !deductible.amount.gt(Decimal.of(0))) {
      return deductible;
    }
    const discount = parameters.require(ParameterCodes.PCT_DESCUENTO_DED_VIP);
    return {
      amount: percentOf(deductible.amount, Decimal.of(100).minus(discount)),
      observations: deductible.observations.with(Marks.DESCUENTO_VIP),
    };
  }
}

/** Calcula el deducible final: estrategia por tipo y luego descuento VIP. */
export class DeductibleService {
  readonly vipDiscount: VipDeductibleDiscount;

  constructor(vipDiscount: VipDeductibleDiscount) {
    this.vipDiscount = vipDiscount;
  }

  /**
   * @rule R-012
   * @rule R-013
   * @rule R-014
   */
  calculate(
    request: LiquidationRequest,
    base: Decimal,
    parameters: BusinessParameters,
    observations: AmountWithMarks['observations'],
  ): AmountWithMarks {
    const strategy = selectDeductibleStrategy(request.deductibleType);
    const raw = strategy.calculate(base, request.deductibleValue, parameters, observations);
    return this.vipDiscount.apply(request.customerCategory, raw, parameters);
  }
}

import { Decimal } from '../shared/decimal.ts';
import { percentOf } from '../model/Rounding.ts';

/**
 * covered = ROUND((base - deducible) * coverage_percentage / 100, 2).
 * @rule R-015
 * @rule R-025
 */
export function coveredAmount(base: Decimal, deductible: Decimal, coveragePercentage: Decimal): Decimal {
  return percentOf(base.minus(deductible), coveragePercentage);
}

/**
 * Un monto cubierto nulo o negativo implica rechazo por BAJO_DEDUCIBLE.
 * @rule R-016
 */
export function isBelowDeductible(covered: Decimal): boolean {
  return covered.lte(Decimal.of(0));
}

