/** Penalización por alta siniestralidad en los 365 días previos. */
export class ClaimsHistoryPenalty {
  /**
   * @rule R-017
   * @rule R-025
   */
  apply(priorClaims: Decimal, covered: Decimal, parameters: BusinessParameters, observations: Observations): AmountWithMarks {
    const maxClaims = parameters.require(ParameterCodes.MAX_SINIESTROS_ANUAL);
    if (priorClaims.lt(maxClaims)) {
      return { amount: covered, observations };
    }
    const penalty = parameters.require(ParameterCodes.PCT_PENALIZACION_SINIEST);
    return {
      amount: percentOf(covered, Decimal.of(100).minus(penalty)),
      observations: observations.with(Marks.PENALIZACION_SINIESTRALIDAD),
    };
  }
}

