import { toAmount, zeroAmount } from '../model/Rounding.ts';

export interface SumInsuredResult extends AmountWithMarks {
  readonly exhausted: boolean;
}

/** Suma asegurada remanente: agotamiento y tope. */
export class SumInsuredLimit {
  /** @rule R-018 */
  apply(sumInsured: Decimal, totalIndemnified: Decimal, covered: Decimal, observations: Observations): SumInsuredResult {
    const remaining = sumInsured.minus(totalIndemnified);
    if (remaining.lte(Decimal.of(0))) {
      return { exhausted: true, amount: zeroAmount(), observations };
    }
    if (covered.gt(remaining)) {
      return { exhausted: false, amount: toAmount(remaining), observations: observations.with(Marks.TOPE_SUMA_ASEGURADA) };
    }
    return { exhausted: false, amount: covered, observations };
  }
}

