/** Retención impositiva: no aplica al ramo VIDA ni a montos que no superan el umbral. */
export class WithholdingCalculator {
  /**
   * @rule R-019
   * @rule R-025
   */
  calculate(lineOfBusiness: string, covered: Decimal, parameters: BusinessParameters, observations: Observations): AmountWithMarks {
    if (lineOfBusiness === Lines.VIDA) {
      return { amount: zeroAmount(), observations };
    }
    const threshold = parameters.require(ParameterCodes.UMBRAL_RETENCION);
    if (!covered.gt(threshold)) {
      return { amount: zeroAmount(), observations };
    }
    const rate = parameters.require(ParameterCodes.TASA_RETENCION);
    return { amount: percentOf(covered, rate), observations: observations.with(Marks.RETENCION_APLICADA) };
  }
}

import type { Decimal } from '../shared/decimal.ts';

/**
 * net = covered - withholding (escala 2, sin redondeo adicional).
 * @rule R-020
 */
export function netAmount(covered: Decimal, withholding: Decimal): Decimal {
  return covered.minus(withholding);
}

