export interface LiquidationPolicies {
  readonly eligibility: EligibilityPipeline;
  readonly baseAmounts: BaseAmountCalculator;
  readonly deductibles: DeductibleService;
  readonly penalty: ClaimsHistoryPenalty;
  readonly sumInsuredLimit: SumInsuredLimit;
  readonly withholding: WithholdingCalculator;
  readonly approval: ApprovalPolicy;
}

/** Servicio de dominio que orquesta la liquidación completa de un siniestro. */
export class ClaimLiquidationService {
  readonly policies: LiquidationPolicies;

  constructor(policies: LiquidationPolicies) {
    this.policies = policies;
  }

  /**
   * Un parámetro inexistente se informa como error 20010.
   * @rule R-003
   */
  liquidate(request: LiquidationRequest, parameters: BusinessParameters): LiquidationOutcome {
    try {
      return this.run(request, parameters);
    } catch (error) {
      if (error instanceof ParameterNotDefinedError) {
        return failure(ErrorCodes.PARAMETER_UNDEFINED);
      }
      throw error;
    }
  }

  /**
   * FACTOR_INFLACION se exige siempre, antes de cualquier validación de negocio.
   * @rule R-001
   * @rule R-003
   * @rule R-004
   * @rule R-023
   */
  private run(request: LiquidationRequest, parameters: BusinessParameters): LiquidationOutcome {
    parameters.require(ParameterCodes.FACTOR_INFLACION);
    if (!isLiquidable(request.claimStatus)) {
      return failure(ErrorCodes.CLAIM_NOT_REGISTERED);
    }
    const verdict = this.policies.eligibility.evaluate(request, parameters);
    if (verdict.rejection !== null) {
      return success(Liquidation.rejected(verdict.rejection, verdict.observations));
    }
    return this.calculate(request, parameters, verdict.observations);
  }

  /**
   * @rule R-011
   * @rule R-015
   * @rule R-016
   */
  private calculate(request: LiquidationRequest, parameters: BusinessParameters, observations: Observations): LiquidationOutcome {
    const base = this.policies.baseAmounts.calculate(request.claimedAmount, request.coverageLimit, observations);
    const deductible = this.policies.deductibles.calculate(request, base.amount, parameters, base.observations);
    const covered = coveredAmount(base.amount, deductible.amount, request.coveragePercentage);
    if (isBelowDeductible(covered)) {
      return success(Liquidation.rejected(ReasonCodes.BAJO_DEDUCIBLE, deductible.observations));
    }
    return this.adjustAndDecide(request, parameters, base.amount, deductible, covered);
  }

  /**
   * @rule R-017
   * @rule R-018
   * @rule R-019
   * @rule R-020
   * @rule R-022
   */
  private adjustAndDecide(
    request: LiquidationRequest,
    parameters: BusinessParameters,
    base: AmountWithMarks['amount'],
    deductible: AmountWithMarks,
    covered: AmountWithMarks['amount'],
  ): LiquidationOutcome {
    const penalized = this.policies.penalty.apply(request.priorLiquidatedClaims365d, covered, parameters, deductible.observations);
    const capped = this.policies.sumInsuredLimit.apply(request.sumInsured, request.totalIndemnified, penalized.amount, penalized.observations);
    if (capped.exhausted) {
      return success(Liquidation.rejected(ReasonCodes.SUMA_ASEGURADA_AGOTADA, capped.observations));
    }
    const withholding = this.policies.withholding.calculate(request.lineOfBusiness, capped.amount, parameters, capped.observations);
    const net = netAmount(capped.amount, withholding.amount);
    const decision = this.policies.approval.decide(request, net, parameters);
    return success(new Liquidation({
      baseAmount: base,
      deductibleAmount: deductible.amount,
      coveredAmount: capped.amount,
      withholdingAmount: withholding.amount,
      netAmount: net,
      status: decision.status,
      reasonCode: decision.reasonCode,
      observations: withholding.observations,
    }));
  }
}

