export interface BatchCandidate {
  readonly claimId: number;
  readonly claimStatus: string;
  readonly reportDate: CalendarDate;
}

export interface BatchSummary {
  readonly processed: number;
  readonly liquidated: number;
  readonly rejected: number;
  readonly pending: number;
  readonly errors: number;
  readonly totalApprovedNet: Decimal;
}

/** Política del proceso por lotes: selección, orden y resumen. */
export class LiquidationBatchPolicy {
  /**
   * Siniestros REGISTRADO con report_date <= process_date, en orden ascendente de identificador.
   * @rule R-027
   */
  select(candidates: readonly BatchCandidate[], processDate: CalendarDate): readonly BatchCandidate[] {
    const eligible = candidates.filter(
      (c) => c.claimStatus === ClaimStatuses.REGISTRADO && !c.reportDate.isAfter(processDate),
    );
    return [...eligible].sort((a, b) => a.claimId - b.claimId);
  }

  /**
   * Contadores del lote y total neto de las liquidaciones aprobadas. Un error cuenta como error y no detiene el lote.
   * @rule R-027
   */
  summarize(outcomes: readonly LiquidationOutcome[]): BatchSummary {
    let liquidated = 0;
    let rejected = 0;
    let pending = 0;
    let errors = 0;
    let total = zeroAmount();
    for (const outcome of outcomes) {
      if (!outcome.ok) {
        errors += 1;
      } else if (outcome.liquidation.status === LiquidationStatuses.APROBADA) {
        liquidated += 1;
        total = total.plus(outcome.liquidation.netAmount);
      } else if (outcome.liquidation.status === LiquidationStatuses.RECHAZADA) {
        rejected += 1;
      } else {
        pending += 1;
      }
    }
    return { processed: outcomes.length, liquidated, rejected, pending, errors, totalApprovedNet: total };
  }
}

