import type { LiquidateClaimCommand } from '../../../application/ports/in/LiquidateClaimPort.ts';
import { BusinessParameters } from '../../../domain/model/BusinessParameters.ts';
import { CalendarDate } from '../../../domain/model/CalendarDate.ts';
import { ErrorCodes } from '../../../domain/model/Codes.ts';
import type { LiquidationRequest } from '../../../domain/model/LiquidationRequest.ts';
import { zeroAmount } from '../../../domain/model/Rounding.ts';

export type MappingResult =
  | { readonly ok: true; readonly command: LiquidateClaimCommand }
  | { readonly ok: false; readonly errorCode: string };

/** Error interno del adaptador de entrada; se convierte en error_code. */
export class InputMappingError extends Error {
  readonly errorCode: string;

  constructor(errorCode: string, message: string) {
    super(message);
    this.name = 'InputMappingError';
    this.errorCode = errorCode;
  }
}

function isAmountText(text: string): boolean {
  return /^-?[0-9]+([.][0-9]+)?$/.test(text);
}

function parseAmount(name: string, text: string): Decimal {
  if (!isAmountText(text)) {
    throw new InputMappingError(ErrorCodes.INVALID_DATA, 'Decimal invalido: ' + name);
  }
  return Decimal.of(text).setScale(2, 'HALF_UP');
}

function parseInteger(name: string, text: string): Decimal {
  if (!/^-?[0-9]+$/.test(text)) {
    throw new InputMappingError(ErrorCodes.INVALID_DATA, 'Entero invalido: ' + name);
  }
  return Decimal.of(text);
}

function parseFlag(name: string, text: string): boolean {
  const value = text.toLowerCase();
  if (value === 'true' || value === '1' || value === 'si' || value === 's') {
    return true;
  }
  if (value === 'false' || value === '0' || value === 'no' || value === 'n') {
    return false;
  }
  throw new InputMappingError(ErrorCodes.INVALID_DATA, 'Booleano invalido: ' + name);
}

/** Lector de campos de texto con conversión a tipos del dominio. */
class FieldReader {
  readonly input: Record<string, string>;

  constructor(input: Record<string, string>) {
    this.input = input;
  }

  raw(name: string): string | null {
    const value = this.input[name];
    if (typeof value !== 'string') {
      return null;
    }
    const trimmed = value.trim();
    return trimmed === '' ? null : trimmed;
  }

  /**
   * Dato obligatorio ausente: equivale a siniestro, póliza o cliente inexistente.
   * @rule R-002
   */
  text(name: string): string {
    const value = this.raw(name);
    if (value === null) {
      throw new InputMappingError(ErrorCodes.NO_DATA_FOUND, 'Dato obligatorio ausente: ' + name);
    }
    return value;
  }

  amount(name: string): Decimal {
    return parseAmount(name, this.text(name));
  }

  optionalAmount(name: string): Decimal {
    const value = this.raw(name);
    return value === null ? zeroAmount() : parseAmount(name, value);
  }

  optionalInteger(name: string): Decimal {
    const value = this.raw(name);
    return value === null ? Decimal.of(0) : parseInteger(name, value);
  }

  flag(name: string): boolean {
    return parseFlag(name, this.text(name));
  }

  date(name: string): CalendarDate {
    const parsed = CalendarDate.fromIso(this.text(name));
    if (parsed === null) {
      throw new InputMappingError(ErrorCodes.INVALID_DATA, 'Fecha invalida: ' + name);
    }
    return parsed;
  }
}

function addParameter(values: Map<string, Decimal>, entry: string): void {
  const trimmed = entry.trim();
  if (trimmed === '') {
    return;
  }
  const separator = trimmed.indexOf('=');
  const name = separator > 0 ? trimmed.slice(0, separator).trim() : '';
  const value = separator > 0 ? trimmed.slice(separator + 1).trim() : '';
  if (name === '' || !isAmountText(value)) {
    throw new InputMappingError(ErrorCodes.INVALID_DATA, 'Parametro invalido');
  }
  values.set(name, Decimal.of(value).setScale(4, 'HALF_UP'));
}

/** Formato esperado: COD=valor;COD=valor */
function parseParameters(raw: string | null): BusinessParameters {
  const values = new Map<string, Decimal>();
  if (raw !== null) {
    for (const entry of raw.split(';')) {
      addParameter(values, entry);
    }
  }
  return new BusinessParameters(values);
}

function buildRequest(reader: FieldReader): LiquidationRequest {
  return {
    claimedAmount: reader.amount('claimed_amount'),
    occurrenceDate: reader.date('occurrence_date'),
    reportDate: reader.date('report_date'),
    processDate: reader.date('process_date'),
    claimStatus: reader.text('claim_status'),
    policyStatus: reader.text('policy_status'),
    policyStartDate: reader.date('policy_start_date'),
    policyEndDate: reader.date('policy_end_date'),
    lineOfBusiness: reader.text('line_of_business'),
    sumInsured: reader.amount('sum_insured'),
    deductibleType: reader.text('deductible_type'),
    deductibleValue: reader.amount('deductible_value'),
    pendingPremium: reader.optionalAmount('pending_premium'),
    customerCategory: reader.text('customer_category'),
    coverageFound: reader.flag('coverage_found'),
    coverageLimit: reader.optionalAmount('coverage_limit'),
    coveragePercentage: reader.optionalAmount('coverage_percentage'),
    waitingDays: reader.optionalInteger('waiting_days'),
    priorLiquidatedClaims365d: reader.optionalInteger('prior_liquidated_claims_365d'),
    totalIndemnified: reader.optionalAmount('total_indemnified'),
  };
}

function buildCommand(reader: FieldReader): LiquidateClaimCommand {
  const parameters = parseParameters(reader.raw('parameters'));
  return { request: buildRequest(reader), parameters };
}

/** Convierte el mapa de cadenas en un comando tipado, o en un código de error. */
export function mapInput(input: Record<string, string>): MappingResult {
  try {
    return { ok: true, command: buildCommand(new FieldReader(input)) };
  } catch (error) {
    if (error instanceof InputMappingError) {
      return { ok: false, errorCode: error.errorCode };
    }
    throw error;
  }
}

