  if (!outcome.ok) {
    return failureRecord(outcome.errorCode);
  }
  const liquidation = outcome.liquidation;
  return {
    base_amount: liquidation.baseAmount.toString(),
    deductible_amount: liquidation.deductibleAmount.toString(),
    covered_amount: liquidation.coveredAmount.toString(),
    withholding_amount: liquidation.withholdingAmount.toString(),
    net_amount: liquidation.netAmount.toString(),
    liquidation_status: liquidation.status,
    reason_code: liquidation.reasonCode,
    observations: liquidation.observations,
    claim_new_status: liquidation.claimNewStatus,
    error_code: '',
  };
}

export function toErrorRecord(errorCode: string): Record<string, string> {
  return failureRecord(errorCode);
}

