/** Adaptador de entrada: cadenas a tipos del dominio, caso de uso y cadenas de salida. */
export class StringLiquidationAdapter {
  readonly useCase: LiquidateClaimPort;

  constructor(useCase: LiquidateClaimPort) {
    this.useCase = useCase;
  }

  handle(input: Record<string, string>): Record<string, string> {
    const mapped = mapInput(input);
    if (!mapped.ok) {
      return toErrorRecord(mapped.errorCode);
    }
    return toOutputRecord(this.useCase.execute(mapped.command));
  }
}

